import{_ as e,g as a,e as r,a4 as c}from"./chunks/framework.CEYJDsBW.js";const p=JSON.parse('{"title":"模板投影与导出位置","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/21.1/packs/export.md","filePath":"ageratum/21.1/packs/export.md"}'),o={name:"ageratum/21.1/packs/export.md"};function d(s,t,n,u,i,l){return a(),r("div",null,[...t[0]||(t[0]=[c('<h1 id="模板投影与导出位置" tabindex="-1">模板投影与导出位置 <a class="header-anchor" href="#模板投影与导出位置" aria-label="Permalink to &quot;模板投影与导出位置&quot;">​</a></h1><p>要用客户端命令投影同一份结构，将压缩二进制模板放在 <code>assets/workshop/ageratum/stands/basic.nbt</code>。按 F3+T 后，在世界中输入下列命令。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ageratum structure workshop:stands/basic ~ ~ ~</span></span></code></pre></div><p>命令索引只扫描 <code>ageratum/</code> 下的 <code>.nbt</code>，将文件夹前缀和扩展名去掉后作为模板 ID。它与正文 <code>structure</code> 标签的直接资源路径不同。模板管理器在客户端重载时接收原始 NBT，实际投影请求到来后再用当前世界的方块注册表装入 <code>StructureTemplate</code>。尚未进入世界时无法实例化模板。<a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/AgeratumStructureTemplateManager.java" target="_blank" rel="noreferrer">模板注册与按需加载</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/command/AgeratumCommand.java" target="_blank" rel="noreferrer">投影命令</a></p><h2 id="从页面导出" tabindex="-1">从页面导出 <a class="header-anchor" href="#从页面导出" aria-label="Permalink to &quot;从页面导出&quot;">​</a></h2><p>打开已加载的结构预览，点击导出按钮。客户端将完整结构压缩并分片发送。服务端校验总大小、顺序、标识与 NBT 结构后，写入<strong>当前世界目录</strong>的 <code>data/ageratum/</code>。文件名只包含命名空间与源文件最后一段。例如 <code>workshop:ageratum/zh_cn/maintenance/stand.snbt</code> 产生 <code>workshop_stand.nbt</code>。再次导出会依次使用 <code>workshop_stand_1.nbt</code>、<code>workshop_stand_2.nbt</code>。</p><table tabindex="0"><thead><tr><th>限制</th><th>值</th><th>处理</th></tr></thead><tbody><tr><td>单次传输</td><td>压缩后最多 8 MiB</td><td>客户端与服务端都会检查大小。</td></tr><tr><td>每片数据</td><td>最多 24 KiB</td><td>服务端要求下一片偏移等于已收字节数。</td></tr><tr><td>解压读取预算</td><td>64 MiB</td><td>用有限额的 NBT 读取器解析。</td></tr><tr><td>新请求间隔与超时</td><td>同一玩家相隔至少 2 秒，传输限时 30 秒</td><td>超时传输会被清理。</td></tr></tbody></table><p>导出位置是存档内的输出目录。要将结果作为下一个资源包版本发布，复制该文件到资源包中的 <code>assets/workshop/ageratum/</code> 并使用相应模板 ID。<a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/StructureExportClient.java" target="_blank" rel="noreferrer">客户端导出</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/network/StructureExportHandler.java" target="_blank" rel="noreferrer">服务端校验</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/structure/StructureExporter.java" target="_blank" rel="noreferrer">文件命名</a></p>',8)])])}const m=e(o,[["render",d]]);export{p as __pageData,m as default};
